import sys
data = sys.stdin.read().split()
n, q = int(data[0]), int(data[1])
parent = list(range(n + 1))
size = [1] * (n + 1)

def find(x):
    root = x
    while parent[root] != root:
        root = parent[root]
    while parent[x] != root:      # path compression, iterative (no recursion limit)
        parent[x], x = root, parent[x]
    return root

out = []
for i in range(q):
    t, a, b = int(data[2 + 3 * i]), int(data[3 + 3 * i]), int(data[4 + 3 * i])
    ra, rb = find(a), find(b)
    if t == 1:
        if ra != rb:
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra        # union by size
            size[ra] += size[rb]
    else:
        out.append("YES" if ra == rb else "NO")
print("\n".join(out))

