const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const parent = Array.from({ length: n + 1 }, (_, i) => i);
const size = new Array(n + 1).fill(1);
const find = (x) => {
  let root = x;
  while (parent[root] !== root) root = parent[root];
  while (parent[x] !== root) { const nx = parent[x]; parent[x] = root; x = nx; }
  return root;
};
const out = [];
for (let i = 0; i < q; i++) {
  const t = tok[2 + 3 * i];
  let ra = find(tok[3 + 3 * i]), rb = find(tok[4 + 3 * i]);
  if (t === 1) {
    if (ra !== rb) {
      if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
      parent[rb] = ra;
      size[ra] += size[rb];
    }
  } else out.push(ra === rb ? "YES" : "NO");
}
