#include <bits/stdc++.h>
using namespace std;
vector<int> parent_, sz_;
int findRoot(int x) {
    int root = x;
    while (parent_[root] != root) root = parent_[root];
    while (parent_[x] != root) {
        int nx = parent_[x];
        parent_[x] = root;
        x = nx;
    }
    return root;
}
int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    parent_.resize(n + 1);
    sz_.assign(n + 1, 1);
    for (int i = 0; i <= n; i++) parent_[i] = i;
    while (q--) {
        int t, a, b;
        scanf("%d %d %d", &t, &a, &b);
        int ra = findRoot(a), rb = findRoot(b);
        if (t == 1) {
            if (ra != rb) {
                if (sz_[ra] < sz_[rb]) swap(ra, rb);
                parent_[rb] = ra;
                sz_[ra] += sz_[rb];
            }
        } else {
            puts(ra == rb ? "YES" : "NO");
        }
    }
    return 0;
}
